// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        vm.prank(nonOwner);
        bool success;
        try c.sudicideAnyone() { success = true; } catch { success = false; }
        assertTrue(!success || c.smartfix_owner() == address(0), "Reference reverts, buggy destroys");
    }
}
